class Solution {
    using G=unordered_map<string,vector<pair<string,double>>>;
    G make(vector<vector<string>>& p,vector<double>& r) {
        G g;
        for(int i=0; i<(int)p.size(); i++) {
            g[p[i][0]].push_back( {
                p[i][1],r[i]
            }
            );
            g[p[i][1]].push_back( {
                p[i][0],1/r[i]
            }
            );
        }
        return g;
    }
    unordered_map<string,double> traverse(G&g,string start) {
        unordered_map<string,double> val;
        queue<string> q;
        q.push(start);
        val[start]=1;
        while(!q.empty()) {
            string u=q.front();
            q.pop();
            for(auto e:g[u])if(!val.count(e.first)) {
                val[e.first]=val[u]*e.second;
                q.push(e.first);
            }
        }
        return val;
    }
    public:double maxAmount(string initialCurrency,vector<vector<string>>& p1,vector<double>& r1,vector<vector<string>>& p2,vector<double>& r2) {
        G g1=make(p1,r1),g2=make(p2,r2);
        auto a=traverse(g1,initialCurrency),b=traverse(g2,initialCurrency);
        double ans=1;
        for(auto x:a)if(b.count(x.first))ans=max(ans,x.second/b[x.first]);
        return ans;
    }
}
